#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-08-31

/**
 * index-budget.mjs - Budget report and rule-based demotion for a memory index (#3741)
 *
 * MEMORY.md is loaded every session, so its size is a permanent per-session cost.
 * dream already trims entry hooks to a byte target, and a PreToolUse guard asks
 * before an over-budget write, but that guard is skipped in bypass mode, which is
 * the population that writes MEMORY.md most, and nothing ever proposed moving old
 * entries out. This script answers "is the index within budget" as a reviewable
 * pass: it reports size by section, names the entries that should move to
 * MEMORY-ARCHIVE.md BY RULE (age + class, never judgement), and keeps the two-file
 * invariant: every memory file is indexed exactly once across MEMORY.md and
 * MEMORY-ARCHIVE.md, every link resolves with exact-case name, one trailer.
 *
 * Usage:
 *   node index-budget.mjs <memory_dir> [--ceiling N] [--handoff-days 7] [--entry-days 30]
 *                         [--apply] [--json] [--help]
 *
 * Default is READ-ONLY: report + proposed moves. --apply rotates MEMORY.md to
 * .MEMORY.md.prev first, performs the moves, re-verifies, and exits 1 if the
 * invariant fails. Nothing is ever deleted.
 *
 * Demotion rule (binds every author equally):
 *   - "## Handoffs" entries older than --handoff-days (date from the filename
 *     project_handoff_YYYY_MM_DD, else file mtime)
 *   - "## Feedback" and "## Project" entries whose file mtime is older than --entry-days
 *   - never: hub_* files, anything under "## Policy", user_* files, anything modified
 *     within 7 days
 *   Oldest first within each class, handoffs first, until the projected size <= ceiling.
 *
 * Ceiling: --ceiling, else ORK_CONTEXT_FILE_BUDGET_BYTES, else 17408 (the same
 * figure the PreToolUse guard reads; the "~24 KB hard read limit" failed to
 * reproduce twice and is not used here).
 *
 * Exit codes: 0 ok · 1 invariant failed after --apply · 2 usage
 */

import { readFileSync, writeFileSync, existsSync, readdirSync, statSync, copyFileSync } from 'node:fs';
import { join, basename } from 'node:path';

const DAY_MS = 24 * 60 * 60 * 1000;
const ENTRY_RE = /^- \[(.+?)\]\(([^)]+\.md)\)/;
const TRAILER_RE = /^> \d+ memory files/;
const NEVER_MOVE_PREFIX = ['hub_', 'user_'];
const NEVER_MOVE_SECTION = new Set(['Policy']);
const FRESH_MS = 7 * DAY_MS;

function usage(code) {
  process.stdout.write(`Usage: node index-budget.mjs <memory_dir> [--ceiling N] [--handoff-days 7] [--entry-days 30] [--apply] [--json] [--help]\n`);
  process.exit(code);
}

const argv = process.argv.slice(2);
const opts = { dir: '', ceiling: 0, handoffDays: 7, entryDays: 30, apply: false, json: false };
for (let i = 0; i < argv.length; i++) {
  const a = argv[i];
  if (a === '--help' || a === '-h') usage(0);
  else if (a === '--apply') opts.apply = true;
  else if (a === '--json') opts.json = true;
  else if (a === '--ceiling') opts.ceiling = Number.parseInt(argv[++i] ?? '', 10);
  else if (a === '--handoff-days') opts.handoffDays = Number.parseInt(argv[++i] ?? '', 10);
  else if (a === '--entry-days') opts.entryDays = Number.parseInt(argv[++i] ?? '', 10);
  else if (a.startsWith('-')) { process.stderr.write(`index-budget: unknown argument ${a}\n`); usage(2); }
  else if (!opts.dir) opts.dir = a;
  else { process.stderr.write(`index-budget: unexpected argument ${a}\n`); usage(2); }
}
if (!opts.dir) { process.stderr.write('index-budget: <memory_dir> is required\n'); usage(2); }
for (const k of ['handoffDays', 'entryDays']) if (!Number.isFinite(opts[k]) || opts[k] < 0) { process.stderr.write(`index-budget: --${k} must be a non-negative integer\n`); usage(2); }
if (!opts.ceiling) {
  const env = Number.parseInt(process.env.ORK_CONTEXT_FILE_BUDGET_BYTES ?? '', 10);
  opts.ceiling = Number.isFinite(env) && env > 0 ? env : 17 * 1024;
}

const MAIN = join(opts.dir, 'MEMORY.md');
const ARCHIVE = join(opts.dir, 'MEMORY-ARCHIVE.md');
if (!existsSync(MAIN)) { process.stderr.write(`index-budget: ${MAIN} not found\n`); process.exit(2); }

/** Parse an index file into entries with their section, line text and byte length. */
function parseIndex(text) {
  const entries = [];
  let section = '(none)';
  let trailers = 0;
  let overhead = 0;
  let trailerBytes = 0;
  for (const line of text.split('\n')) {
    const h = /^## (.+?)(?: \(\d+\))?\s*$/.exec(line);
    if (h) { section = h[1].trim(); overhead += Buffer.byteLength(line, 'utf8') + 1; continue; }
    const m = ENTRY_RE.exec(line);
    if (m) {
      entries.push({ title: m[1], file: m[2], section, line, bytes: Buffer.byteLength(line, 'utf8') + 1 });
      continue;
    }
    if (TRAILER_RE.test(line)) { trailers++; trailerBytes += Buffer.byteLength(line, 'utf8') + 1; }
    overhead += Buffer.byteLength(line, 'utf8') + 1;
  }
  return { entries, trailers, overhead, trailerBytes };
}

function memoryFilesOnDisk(dir) {
  return readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isFile() && d.name.endsWith('.md') && !/^MEMORY/i.test(d.name) && !d.name.startsWith('.'))
    .map((d) => d.name)
    .sort();
}

function handoffDate(file) {
  const m = /project_handoff_(\d{4})_(\d{2})_(\d{2})/.exec(file);
  return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
}

function ageMs(dir, file, now) {
  const fromName = handoffDate(file);
  if (fromName !== null) return now - fromName;
  try { return now - statSync(join(dir, file)).mtimeMs; } catch { return 0; }
}

function mtimeAgeMs(dir, file, now) {
  try { return now - statSync(join(dir, file)).mtimeMs; } catch { return 0; }
}

const mainText = readFileSync(MAIN, 'utf8');
const archiveText = existsSync(ARCHIVE) ? readFileSync(ARCHIVE, 'utf8') : '';
const main = parseIndex(mainText);
const archive = parseIndex(archiveText);
const files = memoryFilesOnDisk(opts.dir);
const fileSet = new Set(files);
const now = Date.now();

// invariant
const indexedMain = main.entries.map((e) => e.file);
const indexedArchive = archive.entries.map((e) => e.file);
const seen = new Map();
for (const f of [...indexedMain, ...indexedArchive]) seen.set(f, (seen.get(f) ?? 0) + 1);
const duplicated = [...seen.entries()].filter(([, n]) => n > 1).map(([f]) => f);
const deadLinks = [...seen.keys()].filter((f) => !fileSet.has(f));
const missing = files.filter((f) => !seen.has(f));
const invariant = {
  files: files.length,
  indexed_main: indexedMain.length,
  indexed_archive: indexedArchive.length,
  missing,
  duplicated,
  dead_links: deadLinks,
  trailer_count_ok: main.trailers === 1,
  ok: missing.length === 0 && duplicated.length === 0 && deadLinks.length === 0 && main.trailers === 1,
};

// report
const bytes = Buffer.byteLength(mainText, 'utf8');
const bySection = new Map();
for (const e of main.entries) {
  const s = bySection.get(e.section) ?? { section: e.section, entries: 0, bytes: 0 };
  s.entries++; s.bytes += e.bytes; bySection.set(e.section, s);
}
const sections = [...bySection.values()].map((s) => ({ ...s, share: bytes ? Math.round((s.bytes / bytes) * 1000) / 10 : 0 }));
const longEntries = main.entries.filter((e) => e.line.length > 400).map((e) => ({ file: e.file, chars: e.line.length }));

// demotion candidates, by rule
function neverMove(e, dir) {
  if (NEVER_MOVE_PREFIX.some((p) => e.file.startsWith(p))) return true;
  if (NEVER_MOVE_SECTION.has(e.section)) return true;
  if (mtimeAgeMs(dir, e.file, now) < FRESH_MS) return true;
  return false;
}
const handoffs = main.entries
  .filter((e) => e.section === 'Handoffs' && !neverMove(e, opts.dir))
  .map((e) => ({ e, age: ageMs(opts.dir, e.file, now) }))
  .filter((x) => x.age > opts.handoffDays * DAY_MS)
  .sort((a, b) => b.age - a.age);
const aged = main.entries
  .filter((e) => (e.section === 'Feedback' || e.section === 'Project') && !neverMove(e, opts.dir))
  .map((e) => ({ e, age: mtimeAgeMs(opts.dir, e.file, now) }))
  .filter((x) => x.age > opts.entryDays * DAY_MS)
  .sort((a, b) => b.age - a.age);

const stamp = new Date().toISOString().slice(0, 10);
function trailerText(movedCount, finalBytes) {
  return `> ${files.length} memory files total. Every file is indexed exactly once across this file and [MEMORY-ARCHIVE.md](MEMORY-ARCHIVE.md); the newest live above, older ones in the archive (read on demand). Last budget pass ${stamp}: ${movedCount} moved, ${finalBytes} B of ${opts.ceiling} B.`;
}
// projection replaces the existing trailer line(s) with the single rewritten one
const base = bytes - main.trailerBytes;
function withTrailer(movedCount, removedBytes) {
  const body = base - removedBytes + 1; // +1 for the blank line before the trailer
  return body + Buffer.byteLength(trailerText(movedCount, body), 'utf8') + 1;
}
const proposed = [];
let removed = 0;
for (const { e, age } of [...handoffs, ...aged]) {
  if (withTrailer(proposed.length, removed) <= opts.ceiling) break;
  proposed.push({ file: e.file, section: e.section, age_days: Math.floor(age / DAY_MS), bytes: e.bytes });
  removed += e.bytes;
}
let projected = withTrailer(proposed.length, removed);
const exhausted = projected > opts.ceiling;

const report = {
  memory_dir: opts.dir,
  ceiling: opts.ceiling,
  bytes,
  percent: Math.round((bytes / opts.ceiling) * 1000) / 10,
  overhead_bytes: main.overhead,
  entries: main.entries.length,
  sections,
  long_entries: longEntries,
  proposed_moves: proposed,
  projected_bytes_after_moves: projected,
  candidates_exhausted: exhausted,
  invariant,
  applied: false,
};

function applyMoves() {
  if (proposed.length === 0) return;
  copyFileSync(MAIN, join(opts.dir, '.MEMORY.md.prev'));
  const moveSet = new Set(proposed.map((p) => p.file));
  const keptLines = [];
  const movedLines = [];
  for (const line of mainText.split('\n')) {
    const m = ENTRY_RE.exec(line);
    if (m && moveSet.has(m[2])) movedLines.push(line); else keptLines.push(line);
  }
  const dirName = basename(opts.dir);
  let archiveOut = archiveText;
  if (!archiveOut.trim()) {
    archiveOut = `# ${dirName} Memory Archive\n\nOlder entries demoted from MEMORY.md by rule. Every memory file is indexed exactly once across MEMORY.md and this file; read on demand.\n`;
  }
  archiveOut = archiveOut.replace(/\s*$/, '\n') + `\n## Moved from MEMORY.md ${stamp} (${movedLines.length})\n` + movedLines.join('\n') + '\n';
  // trailer: exactly one, linking the archive by exact name
  const withoutTrailers = keptLines.filter((l) => !TRAILER_RE.test(l));
  const body = withoutTrailers.join('\n').replace(/\s*$/, '\n') + '\n';
  const mainOut = body + trailerText(movedLines.length, Buffer.byteLength(body, 'utf8')) + '\n';
  writeFileSync(ARCHIVE, archiveOut);
  writeFileSync(MAIN, mainOut);
}

if (opts.apply) {
  applyMoves();
  // re-verify from disk
  const m2 = parseIndex(readFileSync(MAIN, 'utf8'));
  const a2 = parseIndex(existsSync(ARCHIVE) ? readFileSync(ARCHIVE, 'utf8') : '');
  const all = [...m2.entries.map((e) => e.file), ...a2.entries.map((e) => e.file)];
  const cnt = new Map(); for (const f of all) cnt.set(f, (cnt.get(f) ?? 0) + 1);
  report.applied = true;
  report.invariant = {
    files: files.length,
    indexed_main: m2.entries.length,
    indexed_archive: a2.entries.length,
    missing: files.filter((f) => !cnt.has(f)),
    duplicated: [...cnt.entries()].filter(([, n]) => n > 1).map(([f]) => f),
    dead_links: [...cnt.keys()].filter((f) => !fileSet.has(f)),
    trailer_count_ok: m2.trailers === 1,
    ok: false,
  };
  const inv = report.invariant;
  inv.ok = inv.missing.length === 0 && inv.duplicated.length === 0 && inv.dead_links.length === 0 && inv.trailer_count_ok;
  report.bytes_after = Buffer.byteLength(readFileSync(MAIN, 'utf8'), 'utf8');
}

if (opts.json) {
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
} else {
  const lines = [];
  lines.push(`MEMORY.md: ${bytes} B of ${opts.ceiling} B (${report.percent}%), ${main.entries.length} entries, overhead ${main.overhead} B`);
  for (const s of sections) lines.push(`  ${s.section.padEnd(12)} ${String(s.entries).padStart(4)} entries ${String(s.bytes).padStart(7)} B ${String(s.share).padStart(5)}%`);
  if (longEntries.length) lines.push(`  entries over 400 chars: ${longEntries.map((e) => `${e.file} (${e.chars})`).join(', ')}`);
  lines.push(`invariant: files=${invariant.files} main=${invariant.indexed_main} archive=${invariant.indexed_archive} missing=${invariant.missing.length} duplicated=${invariant.duplicated.length} dead_links=${invariant.dead_links.length} trailer_ok=${invariant.trailer_count_ok}`);
  if (proposed.length) {
    lines.push(`proposed moves (${proposed.length}) to MEMORY-ARCHIVE.md, projected ${projected} B:`);
    for (const p of proposed) lines.push(`  ${p.section.padEnd(9)} ${String(p.age_days).padStart(4)}d ${p.file}`);
    if (exhausted) lines.push('  candidates exhausted and still over the ceiling: fall back to hook trimming, then warn');
  } else {
    lines.push(bytes <= opts.ceiling ? 'within budget: no moves proposed' : 'over budget but no rule-eligible candidates: fall back to hook trimming, then warn');
  }
  if (report.applied) lines.push(`applied: MEMORY.md now ${report.bytes_after} B; invariant ${report.invariant.ok ? 'OK' : 'FAILED'}`);
  process.stdout.write(lines.join('\n') + '\n');
}

if (opts.apply && !report.invariant.ok) {
  process.stderr.write('index-budget: invariant failed after apply; .MEMORY.md.prev holds the previous index\n');
  process.exit(1);
}
